import { makeB44, secrets, waitUntil } from '../_shared/b44.ts';
import { t, buildAllReplyActions } from '../_shared/botTranslations.js';
import { tgSend, tgSetCommands } from '../_shared/telegramApi.ts';
import { stateCache, prefetchStates, getState, setState, clearState, getUserContext, findUserByTelegramId } from '../bot/state.ts';
import handleCallback from '../bot/callbacks.ts';
import handleCommand from '../bot/commands.ts';
import { handleDocument, handleBuySearch, handleNumericFlows, handleSellFlow, handleTextFlows } from '../bot/flows.ts';
// Every translated reply-keyboard button text → command action (all languages).
const REPLY_MENU_ACTIONS = buildAllReplyActions();
// Routes one Telegram update: callback query, document upload, or text message.
async function processUpdate(base44, token, update) {
  if (update.callback_query) {
    await handleCallback(base44, token, update.callback_query);
    return;
  }
  const msg = update.message;
  if (!msg) return;
  const chatId = msg.chat.id;
  const text = msg.text || '';
  const tgUser = msg.from;
  if (msg.document && tgUser) {
    await handleDocument(base44, token, msg, tgUser);
    return;
  }
  if (!msg.text || !tgUser) return;
  const replyTo = msg.message_id;
  const tid = String(tgUser.id);
  // The user record plus every per-chat state key this handler may read, in two
  // parallel queries — everything after this hits the cache.
  const [user] = await Promise.all([
    findUserByTelegramId(base44, tid),
    prefetchStates(base44, [
      `lang:${tid}`,
      'setting:premium_hidden',
      'setting:stars_hidden',
      'setting:maintenance_mode',
      'setting:maintenance_message',
      `cmds:${chatId}`,
      `sell:${tid}`,
      `sellseason:${tid}`,
      `adminseason:${tid}`,
      `topup:${tid}`,
      `withdraw:${tid}`,
      `season:${tid}`,
      `buysearch:${tid}`,
      `buypage_query:${tid}`
    ])
  ]);
  const { lang, settings } = await getUserContext(base44, tid);
  if (settings.maintenance_mode && (!user || user.role !== 'admin')) {
    await tgSend(token, chatId, `${t(lang, 'maintenance.title')}\n\n${settings.maintenance_message || t(lang, 'maintenance.body')}`, replyTo);
    return;
  }
  // Each chat's "/" menu is set once: /start for everyone, plus admin uploads.
  // Fire-and-forget — the user's reply must never wait on this.
  if (!stateCache.get(`cmds:${chatId}`)) {
    const cmds = user && user.role === 'admin' ? [
      {
        command: 'start',
        description: '🚀 Start / Main menu'
      },
      {
        command: 'uploadsessions',
        description: '📤 Bulk upload sessions (admin)'
      },
      {
        command: 'adminseason',
        description: '📦 Admin season file upload (no reward)'
      }
    ] : [
      {
        command: 'start',
        description: '🚀 Start / Main menu'
      }
    ];
    waitUntil((async ()=>{
      await tgSetCommands(token, cmds, {
        type: 'chat',
        chat_id: chatId
      });
      await setState(base44, `cmds:${chatId}`, '1');
    })());
  }
  const rawText = text.trim();
  const isMenuPress = !!REPLY_MENU_ACTIONS[rawText];
  const cmd = isMenuPress ? REPLY_MENU_ACTIONS[rawText] : rawText.toLowerCase().split(/\s+/)[0].replace(/^\//, '');
  const ctx = {
    chatId,
    replyTo,
    text: isMenuPress ? '' : text,
    rawText,
    cmd,
    lang,
    settings,
    tgUser,
    user
  };
  const isPlainText = !rawText.startsWith('/') && !isMenuPress;
  if (isPlainText && await getState(base44, `buysearch:${tid}`)) {
    await handleBuySearch(base44, token, ctx);
    return;
  }
  if (isPlainText && /^\d+(\.\d+)?$/.test(rawText)) {
    if (await handleNumericFlows(base44, token, ctx)) return;
  }
  // Tapping a menu button cancels any pending guided flow.
  if (isMenuPress) {
    for (const key of [
      'sell',
      'sellseason',
      'adminseason',
      'topup',
      'withdraw',
      'season',
      'buysearch'
    ]){
      await clearState(base44, `${key}:${tid}`);
    }
  }
  if (isPlainText) {
    const sellStateRec = await getState(base44, `sell:${tid}`);
    if (sellStateRec && await handleSellFlow(base44, token, ctx, JSON.parse(sellStateRec.value))) return;
    if (user && await handleTextFlows(base44, token, ctx)) return;
  }
  await handleCommand(base44, token, ctx);
}
export default async function(req) {
  try {
    const base44 = makeB44(req);
    // Fresh cache per request so state is never stale across updates.
    stateCache.clear();
    const token = secrets.get('TELEGRAM_BOT_TOKEN');
    if (!token) return Response.json({
      error: 'TELEGRAM_BOT_TOKEN not set'
    }, {
      status: 500
    });
    // Only /start is visible in the global "/" menu; admin chats get more.
    // Deferred so it never sits in front of the user's reply.
    const ensureDefaultCommands = async ()=>{
      try {
        if (!await getState(base44, 'default_commands_set')) {
          await tgSetCommands(token, [
            {
              command: 'start',
              description: '🚀 Start / Main menu'
            }
          ]);
          await setState(base44, 'default_commands_set', '1');
        }
      } catch (e) {
        console.error('set default commands failed', e.message);
      }
    };
    // Webhook mode: Telegram POSTs one update as the JSON body.
    let update = null;
    try {
      update = await req.json();
    } catch  {
      update = null;
    }
    if (update && update.update_id) {
      // Telegram re-sends an update if the webhook takes too long to answer
      // (code verification can run for a while). Claim the update_id once so a
      // retry is acknowledged instead of processed a second time.
      // One insert only — `key` is unique, so a retry fails here and exits.
      try {
        await base44.asServiceRole.entities.BotState.create({
          key: `upd:${update.update_id}`,
          value: String(Date.now())
        });
      } catch  {
        return Response.json({
          ok: true,
          duplicate: true
        });
      }
      try {
        await processUpdate(base44, token, update);
      } catch (err) {
        console.error('Webhook process error', err.message, err.stack);
        try {
          await tgSend(token, update.message?.chat?.id, `❌ Error: ${err.message}`);
        } catch  {}
      }
      waitUntil(ensureDefaultCommands());
      return Response.json({
        ok: true
      });
    }
    // Polling fallback (used when no webhook is registered).
    await ensureDefaultCommands();
    const offsetRec = await getState(base44, 'telegram_offset');
    const offset = offsetRec ? parseInt(offsetRec.value) : 0;
    const poll = ()=>fetch(`https://api.telegram.org/bot${token}/getUpdates?offset=${offset}&timeout=30&limit=20`, {
        method: 'POST'
      });
    let updatesData = await (await poll()).json();
    // A still-active webhook makes getUpdates return 409 — drop it and retry.
    if (!updatesData.ok && updatesData.error_code === 409) {
      try {
        await fetch(`https://api.telegram.org/bot${token}/deleteWebhook`, {
          method: 'POST'
        });
        updatesData = await (await poll()).json();
      } catch (e) {
        console.error('deleteWebhook failed', e.message);
      }
    }
    if (!updatesData.ok) return Response.json({
      error: updatesData.description
    }, {
      status: 500
    });
    const updates = updatesData.result || [];
    let lastId = offset;
    for (const u of updates){
      try {
        await processUpdate(base44, token, u);
        if (u.update_id >= lastId) lastId = u.update_id + 1;
      } catch (err) {
        console.error('Error processing update', u.update_id, err.message);
      }
    }
    if (lastId > offset) await setState(base44, 'telegram_offset', String(lastId));
    return Response.json({
      ok: true,
      processed: updates.length,
      offset: lastId
    });
  } catch (error) {
    return Response.json({
      error: error.message
    }, {
      status: 500
    });
  }
}
// Per-request BotState cache + user lookups for the Telegram bot.
// Direct port of the state helpers from base44 pollTelegramUpdates.
// Request-scoped cache so the same key is never queried twice while handling
// one update — the bot's biggest latency source.
export const stateCache = new Map();
// Fetch many keys in ONE query and cache them (misses cached as null).
export async function prefetchStates(base44, keys) {
  const missing = keys.filter((k)=>!stateCache.has(k));
  if (!missing.length) return;
  let records = [];
  try {
    records = await base44.asServiceRole.entities.BotState.filter({
      key: {
        $in: missing
      }
    });
  } catch  {}
  for (const k of missing)stateCache.set(k, null);
  for (const r of records)stateCache.set(r.key, r);
}
export async function getState(base44, key) {
  if (stateCache.has(key)) return stateCache.get(key);
  const records = await base44.asServiceRole.entities.BotState.filter({
    key
  });
  const rec = records[0] || null;
  stateCache.set(key, rec);
  return rec;
}
export async function setState(base44, key, value) {
  const existing = await getState(base44, key);
  if (existing) {
    await base44.asServiceRole.entities.BotState.update(existing.id, {
      value: String(value)
    });
    stateCache.set(key, {
      ...existing,
      value: String(value)
    });
  } else {
    const created = await base44.asServiceRole.entities.BotState.create({
      key,
      value: String(value)
    });
    stateCache.set(key, created || null);
  }
}
export async function clearState(base44, key) {
  const existing = await getState(base44, key);
  if (existing) await base44.asServiceRole.entities.BotState.delete(existing.id);
  stateCache.set(key, null);
}
// Combined fetch of user language + public settings in a SINGLE BotState query.
export async function getUserContext(base44, telegramId) {
  try {
    const keys = [
      `lang:${String(telegramId)}`,
      'setting:premium_hidden',
      'setting:stars_hidden',
      'setting:maintenance_mode',
      'setting:maintenance_message'
    ];
    await prefetchStates(base44, keys);
    const map = {};
    for (const k of keys){
      const rec = stateCache.get(k);
      if (rec) map[k] = rec.value;
    }
    return {
      lang: map[`lang:${String(telegramId)}`] || 'en',
      settings: {
        premium_hidden: map['setting:premium_hidden'] === 'true',
        stars_hidden: map['setting:stars_hidden'] === 'true',
        maintenance_mode: map['setting:maintenance_mode'] === 'true',
        maintenance_message: map['setting:maintenance_message'] || ''
      }
    };
  } catch  {
    return {
      lang: 'en',
      settings: {
        premium_hidden: false,
        stars_hidden: false,
        maintenance_mode: false,
        maintenance_message: ''
      }
    };
  }
}
// Resolves the person behind a Telegram id. The Telegram identity is the single
// money key, so every balance/order lookup runs against it — no app account
// (User row) is required.
export async function findUserByTelegramId(base44, telegramId) {
  const id = String(telegramId);
  const identityEmail = `tg${id}@telegram.local`;
  // Both lookups in parallel — one round-trip instead of two.
  const [users, webUsers] = await Promise.all([
    base44.asServiceRole.entities.User.filter({
      telegram_id: id
    }),
    base44.asServiceRole.entities.TgWebUser.filter({
      telegram_id: id
    })
  ]);
  if (users[0]) {
    return {
      ...users[0],
      login_email: users[0].email,
      email: identityEmail
    };
  }
  const w = webUsers[0];
  if (w && w.banned) return null;
  return {
    id: w?.id || null,
    email: identityEmail,
    login_email: null,
    role: 'user',
    telegram_id: id,
    telegram_username: w?.telegram_username || '',
    telegram_first_name: w?.telegram_first_name || '',
    telegram_last_name: w?.telegram_last_name || ''
  };
}
export async function findUserByBindCode(base44, code) {
  const users = await base44.asServiceRole.entities.User.list();
  const upper = String(code).toUpperCase();
  return users.find((u)=>(u.telegram_bind_code || '').toUpperCase() === upper) || null;
}
import { t, langName } from '../_shared/botTranslations.js';
import { tgSend, tgDeleteMessage, tgSendMenu, tgAnswerCallback, tgEditMenu, tgSendReplyKeyboard } from '../_shared/telegramApi.ts';
import { getRealBalance } from '../_shared/balance.ts';
import { buildRewardsPage } from '../_shared/rewardViews.js';
import { buySeasonInChunks } from '../_shared/seasonBuy.js';
import { getState, setState, clearState, getUserContext, findUserByTelegramId } from './state.ts';
import { mainMenuKeyboard, buyMenuKeyboard, buildCountryKeyboard, mainReplyKeyboard, DEPOSIT_ADDRESSES } from './keyboards.ts';
import { formatOrders, formatStatus, formatProducts } from './views.ts';
import { deliverSeasonZip, handleBind, errText } from './delivery.ts';
// Handles every inline-keyboard button press. Direct port of the callback
// section of the Base44 bot handler.
export default async function handleCallback(base44, token, cq) {
  const cbChatId = cq.message?.chat?.id;
  const cbMsgId = cq.message?.message_id;
  let cbData = cq.data || '';
  // "Buy Again" reuses the original purchase actions.
  if (cbData.startsWith('buyagain1:')) cbData = cbData.replace('buyagain1:', 'buy1:');
  if (cbData.startsWith('buyagainseason:')) cbData = cbData.replace('buyagainseason:', 'seasonconfirm:');
  const cbUser = cq.from;
  await tgAnswerCallback(token, cq.id);
  // Same behaviour as the language picker: as soon as a pressed button leads to
  // a brand-new message, the old button message is removed — only the resulting
  // message stays. In-place menu navigation (tgEditMenu) keeps its message.
  let hostDeleted = false;
  const dropHost = async ()=>{
    if (hostDeleted || !cbMsgId) return;
    hostDeleted = true;
    try {
      await tgDeleteMessage(token, cbChatId, cbMsgId);
    } catch  {}
  };
  const send = async (chatId, text, replyTo)=>{
    await dropHost();
    return tgSend(token, chatId, text, replyTo);
  };
  const sendMenu = async (chatId, text, keyboard)=>{
    await dropHost();
    return tgSendMenu(token, chatId, text, keyboard);
  };
  const [cbUserRec, cbCtx] = await Promise.all([
    cbUser ? findUserByTelegramId(base44, String(cbUser.id)) : Promise.resolve(null),
    getUserContext(base44, String(cbUser.id))
  ]);
  const cbLang = cbCtx.lang;
  const cbSettings = cbCtx.settings;
  // Maintenance mode blocks everyone but admins.
  if (cbSettings.maintenance_mode && (!cbUserRec || cbUserRec.role !== 'admin')) {
    await send(cbChatId, `${t(cbLang, 'maintenance.title')}\n\n${cbSettings.maintenance_message || t(cbLang, 'maintenance.body')}`);
    return;
  }
  if (cbData.startsWith('buyctry:')) {
    const iso = cbData.split(':')[1];
    const countries = await base44.asServiceRole.entities.Country.filter({
      iso,
      active: true,
      platform: 'tg'
    });
    const country = countries[0];
    if (!country) {
      await send(cbChatId, `❌ Country ${iso} not found.`);
      return;
    }
    const bal = cbUserRec ? await getRealBalance(base44, cbUserRec.email) : 0;
    await tgEditMenu(token, cbChatId, cbMsgId, `${country.flag || '🌍'} <b>${country.name}</b> (${country.iso})\n\n${t(cbLang, 'buy.price')}: $${country.price}/account\n${t(cbLang, 'buy.stock')}: ${country.stock || 0}\n${t(cbLang, 'buy.yourBalance')}: $${bal.toFixed(2)}\n\n${t(cbLang, 'buy.chooseType')}`, [
      [
        {
          text: `${t(cbLang, 'buy.buy1')} ($${country.price})`,
          callback_data: `buy1:${iso}`
        }
      ],
      [
        {
          text: t(cbLang, 'buy.season'),
          callback_data: `buyseason:${iso}`
        }
      ],
      [
        {
          text: t(cbLang, 'buy.back'),
          callback_data: 'buy_list'
        }
      ]
    ]);
    return;
  }
  if (cbData.startsWith('buy1:')) {
    const iso = cbData.split(':')[1];
    if (!cbUserRec) {
      await send(cbChatId, t(cbLang, 'bind.required'));
      return;
    }
    const countries = await base44.asServiceRole.entities.Country.filter({
      iso,
      active: true,
      platform: 'tg'
    });
    const country = countries[0];
    if (!country) {
      await send(cbChatId, `❌ Country ${iso} not found.`);
      return;
    }
    if ((country.stock || 0) < 1) {
      await sendMenu(cbChatId, t(cbLang, 'buy.outOfStock'), [
        [
          {
            text: t(cbLang, 'buy.back'),
            callback_data: `buyctry:${iso}`
          }
        ]
      ]);
      return;
    }
    const bal = await getRealBalance(base44, cbUserRec.email);
    if (bal < country.price) {
      await sendMenu(cbChatId, `${t(cbLang, 'buy.insufficientBalance')}\n\n${t(cbLang, 'buy.insufficientBalanceDesc', {
        balance: bal.toFixed(2),
        price: country.price.toFixed(2)
      })}`, [
        [
          {
            text: t(cbLang, 'buy.back'),
            callback_data: `buyctry:${iso}`
          }
        ]
      ]);
      return;
    }
    await send(cbChatId, t(cbLang, 'buy.purchasing1', {
      iso
    }));
    try {
      const result = await base44.asServiceRole.functions.invoke('purchaseAccount', {
        country_iso: iso,
        quantity: 1,
        user_email: cbUserRec.email
      });
      const data = result.data || result;
      if (data.error) throw new Error(data.error);
      const accountId = data.first_account_id || data.account_ids && data.account_ids[0];
      const accounts = accountId ? await base44.asServiceRole.entities.TgAccount.filter({
        id: accountId
      }) : [];
      const account = accounts[0];
      if (account) {
        let msg = `${t(cbLang, 'buy.purchaseDone')}\n\n`;
        msg += `${country.flag || '🌍'} <b>${country.name}</b> (${country.iso})\n`;
        msg += `💰 ${t(cbLang, 'buy.price')}: $${country.price}\n`;
        msg += `🛡️ 2FA: <b>Disabled</b>\n`;
        msg += `${t(cbLang, 'buy.phone')}: <code>${account.phone_number}</code>\n`;
        // OTP button rides along on the purchase message.
        await sendMenu(cbChatId, msg, [
          [
            {
              text: t(cbLang, 'buy.otpBtn'),
              callback_data: `getotp:${account.id}`
            }
          ]
        ]);
      } else {
        await send(cbChatId, `${t(cbLang, 'buy.purchaseDone')}\n${t(cbLang, 'buy.account')}: <code>${accountId || 'N/A'}</code>`);
      }
    } catch (err) {
      await send(cbChatId, `❌ Error: ${err.message}`);
    }
    return;
  }
  if (cbData.startsWith('buyseason:')) {
    const iso = cbData.split(':')[1];
    if (!cbUserRec) {
      await send(cbChatId, t(cbLang, 'bind.required'));
      return;
    }
    const countries = await base44.asServiceRole.entities.Country.filter({
      iso,
      active: true,
      platform: 'tg'
    });
    const country = countries[0];
    if (!country) {
      await send(cbChatId, `❌ Country ${iso} not found.`);
      return;
    }
    const bal = await getRealBalance(base44, cbUserRec.email);
    const qtyButtons = [
      5,
      10,
      20,
      50,
      100,
      200,
      500,
      1000
    ];
    const keyboard = [];
    for(let i = 0; i < qtyButtons.length; i += 4){
      keyboard.push(qtyButtons.slice(i, i + 4).map((q)=>({
          text: `📦 ${q}`,
          callback_data: `seasonqty:${iso}:${q}`
        })));
    }
    keyboard.push([
      {
        text: t(cbLang, 'buy.seasonCustom'),
        callback_data: `seasoncustom:${iso}`
      }
    ]);
    keyboard.push([
      {
        text: t(cbLang, 'buy.back'),
        callback_data: `buyctry:${iso}`
      }
    ]);
    await tgEditMenu(token, cbChatId, cbMsgId, t(cbLang, 'buy.seasonTitle', {
      name: country.name,
      iso: country.iso,
      price: country.price,
      stock: country.stock || 0,
      balance: bal.toFixed(2)
    }) + '\n\n' + t(cbLang, 'buy.seasonPrompt'), keyboard);
    return;
  }
  if (cbData.startsWith('rewpage:')) {
    const page = parseInt(cbData.split(':')[1]) || 1;
    const { text, keyboard } = await buildRewardsPage(base44, cbLang, page);
    await tgEditMenu(token, cbChatId, cbMsgId, text, keyboard);
    return;
  }
  if (cbData === 'buysearch') {
    await setState(base44, `buysearch:${String(cbUser.id)}`, 'active');
    await send(cbChatId, t(cbLang, 'buy.searchPrompt'));
    return;
  }
  if (cbData.startsWith('buypage:')) {
    const page = parseInt(cbData.split(':')[1]) || 1;
    const queryRec = await getState(base44, `buypage_query:${String(cbUser.id)}`);
    const query = queryRec ? queryRec.value : null;
    const countries = await base44.asServiceRole.entities.Country.filter({
      active: true,
      platform: 'tg'
    });
    if (!countries.length) {
      await send(cbChatId, '❌ No countries available.');
      return;
    }
    await tgEditMenu(token, cbChatId, cbMsgId, query ? t(cbLang, 'buy.searchResult', {
      query
    }) : `${t(cbLang, 'buy.title')}\n\n${t(cbLang, 'buy.prompt')}`, buildCountryKeyboard(countries, cbLang, query, page));
    return;
  }
  if (cbData === 'buy_list') {
    await clearState(base44, `buypage_query:${String(cbUser.id)}`);
    const countries = await base44.asServiceRole.entities.Country.filter({
      active: true,
      platform: 'tg'
    });
    if (!countries.length) {
      await send(cbChatId, '❌ No countries available.');
      return;
    }
    await tgEditMenu(token, cbChatId, cbMsgId, `🌍 <b>Market — Buy Accounts</b>\n\nTap a country:`, buildCountryKeyboard(countries, cbLang, null, 1));
    return;
  }
  if (cbData.startsWith('admintopup:') || cbData.startsWith('adminwithdraw:')) {
    const [kind, recordId, status] = cbData.split(':');
    if (!cbUserRec || cbUserRec.role !== 'admin') {
      await send(cbChatId, '⚠️ Admin only.');
      return;
    }
    await tgAnswerCallback(token, cq.id, 'Processing...');
    const isTopUp = kind === 'admintopup';
    try {
      const result = await base44.asServiceRole.functions.invoke(isTopUp ? 'approveTopUp' : 'approveWithdrawal', isTopUp ? {
        topup_id: recordId,
        status
      } : {
        withdrawal_id: recordId,
        status
      });
      const data = result.data || result;
      if (data.error) throw new Error(data.error);
      await tgEditMenu(token, cbChatId, cbMsgId, `${status === 'approved' ? '✅' : '❌'} <b>${isTopUp ? 'Top-up' : 'Withdrawal'} ${status}</b>\n\nID: <code>${recordId.slice(-8)}</code>\nUser: ${data.user_email || ''}\nBalance: $${data.balance || ''}`, []);
    } catch (err) {
      await send(cbChatId, `❌ Error: ${err.message}`);
    }
    return;
  }
  if (cbData.startsWith('langset:')) {
    const langCode = cbData.split(':')[1];
    await setState(base44, `lang:${String(cbUser.id)}`, langCode);
    const name = langName(langCode);
    await tgAnswerCallback(token, cq.id, `✅ ${name}`);
    await dropHost();
    await tgSendReplyKeyboard(token, cbChatId, t(langCode, 'lang.set', {
      name
    }) + '\n\n' + t(langCode, 'menu.title') + '\n' + t(langCode, 'menu.prompt'), mainReplyKeyboard(langCode, {
      hidePremium: cbSettings.premium_hidden,
      hideStars: cbSettings.stars_hidden
    }));
    return;
  }
  if (cbData.startsWith('buyprodconfirm:')) {
    const productId = cbData.split(':')[1];
    if (!cbUserRec) {
      await send(cbChatId, t(cbLang, 'bind.required'));
      return;
    }
    const products = await base44.asServiceRole.entities.Product.filter({
      id: productId
    });
    const product = products[0];
    if (!product) {
      await send(cbChatId, '❌ Product not found.');
      return;
    }
    const bal = await getRealBalance(base44, cbUserRec.email);
    if (bal < product.price) {
      await sendMenu(cbChatId, `${t(cbLang, 'buy.prodInsufficientBalance')}\n\n${t(cbLang, 'buy.prodInsufficientBalanceDesc', {
        balance: bal.toFixed(2),
        price: product.price.toFixed(2)
      })}`, [
        [
          {
            text: t(cbLang, 'buy.back'),
            callback_data: product.category === 'premium' ? 'menu_premium' : 'menu_stars'
          }
        ]
      ]);
      return;
    }
    await send(cbChatId, t(cbLang, 'buy.prodPurchasing'));
    try {
      const result = await base44.asServiceRole.functions.invoke('purchaseProduct', {
        product_id: productId,
        user_email: cbUserRec.email
      });
      const data = result.data || result;
      if (data.error) throw new Error(data.error);
      await send(cbChatId, `${t(cbLang, 'buy.prodDone')}\n\nProduct: ${data.product_name}\nPrice: $${data.price || ''}\n\nThis product will be sent to your account soon.`);
    } catch (err) {
      await send(cbChatId, `❌ Error: ${err.message}`);
    }
    return;
  }
  if (cbData.startsWith('buyprod:')) {
    const productId = cbData.split(':')[1];
    if (!cbUserRec) {
      await send(cbChatId, t(cbLang, 'bind.required'));
      return;
    }
    const products = await base44.asServiceRole.entities.Product.filter({
      id: productId
    });
    const product = products[0];
    if (!product) {
      await send(cbChatId, '❌ Product not found.');
      return;
    }
    const bal = await getRealBalance(base44, cbUserRec.email);
    await tgEditMenu(token, cbChatId, cbMsgId, `${t(cbLang, 'buy.prodConfirmTitle')}\n\n${t(cbLang, 'buy.prodConfirmProduct', {
      name: product.name
    })}\n${t(cbLang, 'buy.prodConfirmPrice', {
      price: product.price.toFixed(2)
    })}\n${t(cbLang, 'buy.prodConfirmBalance', {
      balance: bal.toFixed(2)
    })}`, [
      [
        {
          text: t(cbLang, 'buy.prodConfirmBtn'),
          callback_data: `buyprodconfirm:${productId}`
        }
      ],
      [
        {
          text: t(cbLang, 'buy.back'),
          callback_data: product.category === 'premium' ? 'menu_premium' : 'menu_stars'
        }
      ]
    ]);
    return;
  }
  if (cbData.startsWith('seasonqty:')) {
    const parts = cbData.split(':');
    const iso = parts[1];
    const qty = parseInt(parts[2]);
    if (!cbUserRec) {
      await send(cbChatId, t(cbLang, 'bind.required'));
      return;
    }
    const countries = await base44.asServiceRole.entities.Country.filter({
      iso,
      active: true,
      platform: 'tg'
    });
    const country = countries[0];
    if (!country) {
      await send(cbChatId, `❌ Country ${iso} not found.`);
      return;
    }
    const stock = country.stock || 0;
    const bal = await getRealBalance(base44, cbUserRec.email);
    const total = Number((country.price * qty).toFixed(2));
    if (stock < qty) {
      await send(cbChatId, t(cbLang, 'buy.seasonInsufficientStock', {
        available: stock,
        qty
      }));
      return;
    }
    if (bal < total) {
      await sendMenu(cbChatId, `${t(cbLang, 'buy.seasonInsufficientBalance')}\n\n${t(cbLang, 'buy.seasonInsufficientBalanceDesc', {
        balance: bal.toFixed(2),
        total: total.toFixed(2)
      })}`, [
        [
          {
            text: t(cbLang, 'buy.back'),
            callback_data: `buyseason:${iso}`
          }
        ]
      ]);
      return;
    }
    await tgEditMenu(token, cbChatId, cbMsgId, `${t(cbLang, 'buy.seasonConfirmTitle')}\n\n${country.flag || '🌍'} <b>${country.name}</b> (${iso})\n${t(cbLang, 'buy.seasonConfirmQty', {
      qty
    })}\n${t(cbLang, 'buy.seasonConfirmCost', {
      total: total.toFixed(2)
    })}\n${t(cbLang, 'buy.seasonConfirmBalance', {
      balance: bal.toFixed(2)
    })}`, [
      [
        {
          text: t(cbLang, 'buy.seasonConfirmBtn'),
          callback_data: `seasonconfirm:${iso}:${qty}`
        }
      ],
      [
        {
          text: t(cbLang, 'buy.back'),
          callback_data: `buyseason:${iso}`
        }
      ]
    ]);
    return;
  }
  if (cbData.startsWith('seasoncustom:')) {
    const iso = cbData.split(':')[1];
    if (!cbUserRec) {
      await send(cbChatId, t(cbLang, 'bind.required'));
      return;
    }
    await setState(base44, `season:${String(cbUser.id)}`, JSON.stringify({
      iso,
      status: 'awaiting_qty'
    }));
    await send(cbChatId, t(cbLang, 'buy.seasonCustomPrompt'));
    return;
  }
  if (cbData.startsWith('seasonconfirm:')) {
    const parts = cbData.split(':');
    const iso = parts[1];
    const qty = parseInt(parts[2]);
    if (!cbUserRec) {
      await send(cbChatId, t(cbLang, 'bind.required'));
      return;
    }
    await send(cbChatId, t(cbLang, 'buy.seasonPurchasing', {
      qty,
      iso
    }));
    try {
      // Bought in chunks with progress updates — any size, no timeout.
      const { ids: accountIds, error: seasonErr } = await buySeasonInChunks(base44, {
        country_iso: iso,
        user_email: cbUserRec.email,
        quantity: qty,
        onChunk: qty > 100 ? async ({ done, total })=>{
          await send(cbChatId, `⏳ ${done}/${total} accounts ready…`);
        } : null
      });
      if (!accountIds.length) throw new Error(seasonErr || 'No accounts could be delivered');
      try {
        await tgDeleteMessage(token, cbChatId, cbMsgId);
      } catch  {}
      const seasonCountry = (await base44.asServiceRole.entities.Country.filter({
        iso,
        platform: 'tg'
      }))[0];
      let msg = `${t(cbLang, 'buy.seasonDone')}\n\n`;
      if (seasonCountry) {
        msg += `${seasonCountry.flag || '🌍'} <b>${seasonCountry.name}</b> (${iso})\n`;
        msg += `💰 ${t(cbLang, 'buy.price')}: $${(seasonCountry.price * qty).toFixed(2)}\n`;
      }
      msg += `${t(cbLang, 'buy.seasonAccounts')}: ${accountIds.length}\n`;
      if (accountIds.length < qty) msg += `⚠️ ${qty - accountIds.length} could not be delivered (not charged)\n`;
      await send(cbChatId, msg);
      await deliverSeasonZip(base44, token, cbChatId, accountIds);
      await sendMenu(cbChatId, `✅`, [
        [
          {
            text: t(cbLang, 'buy.buyAgain'),
            callback_data: `buyagainseason:${iso}:${qty}`
          }
        ]
      ]);
    } catch (err) {
      await send(cbChatId, `❌ Error: ${errText(err)}`);
    }
    return;
  }
  if (cbData.startsWith('getotp:')) {
    const accountId = cbData.split(':')[1];
    if (!cbUserRec) {
      await send(cbChatId, t(cbLang, 'bind.required'));
      return;
    }
    const fetchingMsg = await send(cbChatId, t(cbLang, 'buy.otpFetching'));
    const fetchingMsgId = fetchingMsg?.result?.message_id;
    try {
      const result = await base44.asServiceRole.functions.invoke('fetchOtpCode', {
        account_id: accountId,
        user_email: cbUserRec.email
      });
      const data = result.data || result;
      if (data.error) throw new Error(data.error);
      const acc = (await base44.asServiceRole.entities.TgAccount.filter({
        id: accountId
      }))[0];
      try {
        if (fetchingMsgId) await tgDeleteMessage(token, cbChatId, fetchingMsgId);
      } catch  {}
      await sendMenu(cbChatId, `${t(cbLang, 'buy.otpResult')}\n\n${t(cbLang, 'buy.account')}: <code>${accountId}</code>\n${t(cbLang, 'buy.otpCode')}: <code>${data.code || data.otp_code || 'N/A'}</code>\n${t(cbLang, 'buy.otpPass')}: <code>${data.pass || 'N/A'}</code>`, [
        [
          {
            text: t(cbLang, 'buy.buyAgain'),
            callback_data: `buyagain1:${acc?.country_iso || ''}`
          }
        ]
      ]);
    } catch (err) {
      try {
        if (fetchingMsgId) await tgDeleteMessage(token, cbChatId, fetchingMsgId);
      } catch  {}
      await send(cbChatId, t(cbLang, 'buy.otpError'));
    }
    return;
  }
  if (cbData === 'sell_number') {
    if (!cbUserRec) {
      await send(cbChatId, t(cbLang, 'bind.required'));
      return;
    }
    await setState(base44, `sell:${String(cbUser.id)}`, JSON.stringify({
      status: 'awaiting_phone'
    }));
    await send(cbChatId, `${t(cbLang, 'sell.title')}\n\n${t(cbLang, 'sell.prompt')}`);
    return;
  }
  if (cbData === 'sell_season') {
    if (!cbUserRec) {
      await send(cbChatId, t(cbLang, 'bind.required'));
      return;
    }
    await setState(base44, `sellseason:${String(cbUser.id)}`, JSON.stringify({
      status: 'awaiting_sessions'
    }));
    await send(cbChatId, t(cbLang, 'sell.seasonPrompt'));
    return;
  }
  switch(cbData){
    case 'menu_main':
      await tgEditMenu(token, cbChatId, cbMsgId, t(cbLang, 'menu.mainMsg'), mainMenuKeyboard(cbLang, {
        hidePremium: cbSettings.premium_hidden,
        hideStars: cbSettings.stars_hidden
      }));
      break;
    case 'menu_buy':
      await tgEditMenu(token, cbChatId, cbMsgId, t(cbLang, 'buy.menuMsg'), buyMenuKeyboard(cbLang));
      break;
    case 'buy_single':
      {
        if (!cbUserRec) {
          await send(cbChatId, t(cbLang, 'bind.required'));
          break;
        }
        await clearState(base44, `buypage_query:${String(cbUser.id)}`);
        const countries = await base44.asServiceRole.entities.Country.filter({
          active: true,
          platform: 'tg'
        });
        if (!countries.length) {
          await send(cbChatId, '❌ No countries available.');
          break;
        }
        await sendMenu(cbChatId, `${t(cbLang, 'buy.title')}\n\n${t(cbLang, 'buy.prompt')}`, buildCountryKeyboard(countries, cbLang, null, 1));
        break;
      }
    case 'buy_season':
      {
        if (!cbUserRec) {
          await send(cbChatId, t(cbLang, 'bind.required'));
          break;
        }
        await send(cbChatId, `📦 <b>Season Purchase</b>\n\nUsage: <code>/season [ISO] [quantity>1]</code>\nExample: <code>/season US 5</code>`);
        break;
      }
    case 'menu_balance':
      {
        if (!cbUserRec) {
          await send(cbChatId, t(cbLang, 'bind.required'));
          break;
        }
        const bal = await getRealBalance(base44, cbUserRec.email);
        await send(cbChatId, `${t(cbLang, 'balance.title')}\n\n$${bal.toFixed(2)}`);
        break;
      }
    case 'menu_topup':
      {
        if (!cbUserRec) {
          await send(cbChatId, t(cbLang, 'bind.required'));
          break;
        }
        const topupPromptMsg = await send(cbChatId, `💳 <b>Top Up Balance</b>\n\nPlease type the amount you want to top up:\nExample: <code>50</code>`);
        // Every message of this flow is tracked so it can be wiped on submit.
        await setState(base44, `topup:${String(cbUser.id)}`, JSON.stringify({
          amount: null,
          status: 'awaiting_amount',
          msgs: [
            topupPromptMsg?.result?.message_id
          ].filter(Boolean)
        }));
        break;
      }
    case 'topup_usdt':
      {
        if (!cbUserRec) {
          await send(cbChatId, t(cbLang, 'bind.required'));
          break;
        }
        const topupStateRec = await getState(base44, `topup:${String(cbUser.id)}`);
        if (!topupStateRec) {
          await send(cbChatId, '❌ Session expired. Use /topup again.');
          break;
        }
        const topupState = JSON.parse(topupStateRec.value);
        const amount = topupState.amount;
        const addressKeyboard = DEPOSIT_ADDRESSES.map((a)=>[
            {
              text: `📋 Copy ${a.label}`,
              copy_text: {
                text: a.address
              }
            }
          ]);
        const addrMsg = await sendMenu(cbChatId, `📋 <b>Manual Deposit — $${amount} USDT</b>\n\nSend exactly $${amount} USDT to one of these addresses. Tap a button to copy:\n\nAfter sending, reply with your <b>TXID</b> (transaction hash).`, addressKeyboard);
        await setState(base44, `topup:${String(cbUser.id)}`, JSON.stringify({
          amount,
          status: 'awaiting_txid',
          msgs: [
            ...topupState.msgs || [],
            cbMsgId,
            addrMsg?.result?.message_id
          ].filter(Boolean)
        }));
        break;
      }
    case 'topup_okpay':
      {
        if (!cbUserRec) {
          await send(cbChatId, t(cbLang, 'bind.required'));
          break;
        }
        const topupStateRec = await getState(base44, `topup:${String(cbUser.id)}`);
        if (!topupStateRec) {
          await send(cbChatId, '❌ Session expired. Use /topup again.');
          break;
        }
        const amount = JSON.parse(topupStateRec.value).amount;
        await send(cbChatId, `🔄 Creating OKPay order for $${amount}...`);
        try {
          const result = await base44.asServiceRole.functions.invoke('createOkpayOrder', {
            amount,
            coin: 'USDT',
            user_email: cbUserRec.email
          });
          const data = result.data || result;
          if (data.error) throw new Error(data.error);
          const payUrl = data.pay_url || data.payment_url || data.url;
          if (payUrl) {
            await sendMenu(cbChatId, `✅ <b>OKPay Order Created</b>\n\nAmount: $${amount}\n\nTap the button below to pay:`, [
              [
                {
                  text: '⚡ Pay with OKPay',
                  url: payUrl
                }
              ]
            ]);
          } else {
            await send(cbChatId, `✅ <b>OKPay Order Created</b>\n\nAmount: $${amount}\nCheck app for payment link.`);
          }
          await clearState(base44, `topup:${String(cbUser.id)}`);
        } catch (err) {
          await send(cbChatId, `❌ Error: ${err.message}`);
        }
        break;
      }
    case 'menu_status':
      {
        if (!cbUserRec) {
          await send(cbChatId, t(cbLang, 'bind.required'));
          break;
        }
        await send(cbChatId, await formatStatus(base44, cbUserRec.email, cbLang));
        break;
      }
    case 'menu_orders':
      {
        if (!cbUserRec) {
          await send(cbChatId, t(cbLang, 'bind.required'));
          break;
        }
        await send(cbChatId, await formatOrders(base44, cbUserRec.email, cbLang));
        break;
      }
    case 'menu_premium':
      {
        if (cbSettings.premium_hidden) {
          await send(cbChatId, t(cbLang, 'premium.unavailable'));
          break;
        }
        await send(cbChatId, await formatProducts(base44, 'premium', cbLang));
        break;
      }
    case 'menu_stars':
      {
        if (cbSettings.stars_hidden) {
          await send(cbChatId, t(cbLang, 'stars.unavailable'));
          break;
        }
        await send(cbChatId, await formatProducts(base44, 'stars', cbLang));
        break;
      }
    case 'menu_bind':
      await dropHost();
      await handleBind(base44, token, cbChatId, cbUser, cbLang, findUserByTelegramId);
      break;
    case 'menu_help':
      await send(cbChatId, `${t(cbLang, 'help.title')}\n\n${t(cbLang, 'help.body')}`);
      break;
  }
}
// Reward-related message builders used by the Telegram bot.
// Kept out of pollTelegramUpdates to keep that handler small.
import { t } from './botTranslations.js';

const REWARD_PAGES = 4;

// Build one page of the reward-price list plus its Back/Next keyboard.
// The full list is always split into exactly REWARD_PAGES pages.
export async function buildRewardsPage(base44, lang, page) {
  const L = lang || 'en';
  const rewards = await base44.asServiceRole.entities.RewardPrice.filter({ active: true });
  if (!rewards.length) {
    return { text: `${t(L, 'rewards.title')}\n\nNo reward prices available.`, keyboard: [] };
  }
  const perPage = Math.ceil(rewards.length / REWARD_PAGES);
  const totalPages = Math.max(1, Math.ceil(rewards.length / perPage));
  const current = Math.min(Math.max(1, page || 1), totalPages);
  const items = rewards.slice((current - 1) * perPage, current * perPage);
  const lines = items.map(r =>
    `${r.flag || '🌍'} <b>${r.country_name || r.country_iso}</b> (${r.dial_code || ''}) — $${r.reward_price}`
  );
  const nav = [];
  if (current > 1) nav.push({ text: `⬅️ ${t(L, 'buy.back')}`, callback_data: `rewpage:${current - 1}` });
  nav.push({ text: `${current}/${totalPages}`, callback_data: 'noop' });
  if (current < totalPages) nav.push({ text: `${t(L, 'buy.next')} ➡️`, callback_data: `rewpage:${current + 1}` });
  return {
    text: `${t(L, 'rewards.title')}\n\n${lines.join('\n')}`,
    keyboard: [nav],
  };
}

// Build the pending + credited reward summary for one user.
export async function buildUserRewards(base44, email) {
  const sessions = await base44.asServiceRole.entities.SessionRequest.filter({
    user_email: email,
    status: 'completed',
  });
  const now = Date.now();
  let text = '';
  const pending = sessions.filter(s => (s.reward_status === 'pending' || s.reward_status === 'frozen') && s.reward_eligible_at);
  if (pending.length) {
    text += `\n\n⏳ <b>Pending Rewards</b>\n`;
    for (const s of pending) {
      const diff = new Date(s.reward_eligible_at).getTime() - now;
      const flag = s.reward_status === 'frozen' ? '🧊 ' : '';
      if (diff > 0) {
        const days = Math.floor(diff / 86400000);
        const hours = Math.floor((diff % 86400000) / 3600000);
        const mins = Math.floor((diff % 3600000) / 60000);
        text += `${flag}• <code>${s.phone_number}</code> — ${days}d ${hours}h ${mins}m | $${s.reward_amount || 0}\n`;
      } else {
        text += `${flag}• <code>${s.phone_number}</code> — ✅ Ready | $${s.reward_amount || 0}\n`;
      }
    }
  }
  const rewarded = sessions.filter(s => s.reward_status === 'rewarded');
  if (rewarded.length) {
    text += `\n✅ <b>Credited Rewards (${rewarded.length})</b>\n`;
    for (const s of rewarded.slice(-10)) {
      text += `• <code>${s.phone_number}</code> — $${s.reward_amount || 0}\n`;
    }
  }
  return text;
}// Buys a season of any size by calling purchaseAccount in chunks.
// Each call delivers what it can inside its own time budget and reports the
// remainder, so a 1000+ account order never hits a function timeout.
const CHUNK = 100;

export async function buySeasonInChunks(base44, { country_iso, user_email, quantity, onChunk }) {
  const ids = [];
  let batchId = '';
  let error = null;

  while (ids.length < quantity) {
    const ask = Math.min(CHUNK, quantity - ids.length);
    let data;
    try {
      const res = await base44.asServiceRole.functions.invoke('purchaseAccount', {
        country_iso,
        quantity: ask,
        user_email,
        purchase_type: 'season',
        batch_id: batchId || undefined,
      });
      data = res.data || res;
      if (data.error) throw new Error(data.error);
    } catch (e) {
      error = e?.message || String(e);
      break;
    }
    const got = data.account_ids || [];
    if (!got.length) break;
    if (!batchId && data.batch_id) batchId = data.batch_id;
    ids.push(...got);
    if (onChunk) await onChunk({ done: ids.length, total: quantity, ids: got });
  }

  return { ids, batchId, error: ids.length ? null : error };
}import { t, buildReplyKeyboard } from '../_shared/botTranslations.js';
