	y.on('foo', function () {
		++count2;
	});
	z.on('foo', function () {
		++count3;
	});

	x.emit('foo');
	a(count, 1, "Pre pipe, x");
	a(count2, 0, "Pre pipe, y");
	a(count3, 0, "Pre pipe, z");

	pipe = t(x, y);
