/**
 * is bigint x equal to integer y?
 *
 * y must have less than bpe bits
 *
 * @export
 * @param {number[]} x
 * @param {number} y
 * @returns {(1 | 0)}
 */
export function equalsInt(x: number[], y: number): Bool {
  var i
  if (x[0] != y) return 0
  for (i = 1; i < x.length; i++) if (x[i]) return 0
  return 1
}

/**
 * are bigints x and y equal?
 *
 * this works even if x and y are different lengths and have arbitrarily many leading zeros
 *
 * @param {number[]} x
 * @param {number[]} y
 * @returns {(1 | 0)}
 */
export function equals(x: number[], y: number[]): Bool {
  var i
  var k = x.length < y.length ? x.length : y.length
  for (i = 0; i < k; i++) if (x[i] !== y[i]) return 0
  if (x.length > y.length) {
    for (; i < x.length; i++) if (x[i]) return 0
  } else {
    for (; i < y.length; i++) if (y[i]) return 0
  }
  return 1
}

/**
 * is the bigInt x equal to zero?
 *
 * @export
 * @param {number[]} x
 * @returns {(1 | 0)}
 */
export function isZero(x: number[]): Bool {
  var i
  for (i = 0; i < x.length; i++) if (x[i]) return 0
  return 1
}

/**
 * Convert a bigInt into a string in a given base, from base 2 up to base 95.
 *
 * Base -1 prints the contents of the array representing the number.
 *
 * @export
 * @param {number[]} x
 * @param {number} base
 * @returns {string}
 */
export function bigInt2str(x: number[], base: number): string {
  var i,
      t,
      s = ''

  if (s6.length !== x.length) s6 = dup(x)
  else copy_(s6, x)

  if (base === -1) {
    //return the list of array contents
    for (i = x.length - 1; i > 0; i--) s += x[i] + ','
    s += x[0]
  } else {
    //return it in the given base
    while (!isZero(s6)) {
      t = divInt_(s6, base) //t=s6 % base; s6=floor(s6/base);
      s = digitsStr.substring(t, t + 1) + s
    }
  }
  if (s.length === 0) s = '0'
  return s
}

/**
 * Returns a duplicate of bigInt x
 *
 * @export
 * @param {number[]} x
 * @returns {number[]}
 */
export function dup(x: number[]): number[] {
  var i
  buff = Array(x.length)
  copy_(buff, x)
  return buff
}

/**
 * do x=y on bigInts x and y.
 *
 * x must be an array at least as big as y (not counting the leading zeros in y).
 *
 * @export
 * @param {number[]} x
 * @param {number[]} y
 * @returns {void}
 */
export function copy_(x: number[], y: number[]): void {
  var i
  var k = x.length < y.length ? x.length : y.length
  for (i = 0; i < k; i++) x[i] = y[i]
  for (i = k; i < x.length; i++) x[i] = 0
}

/**
 * do x=y on bigInt x and integer y.
 *
 * @export
 * @param {number[]} x
 * @param {number} n
 * @returns {void}
 */
export function copyInt_(x: number[], n: number): void {
  var i, c
  var len = x.length //TODO .length in for loop have perfomance costs. Bench this
  for (c = n, i = 0; i < len; i++) {
    x[i] = c & mask
    c >>= bpe
  }
}

/**
 * do x=x+n where x is a bigInt and n is an integer.
 *
 * x must be large enough to hold the result.
 *
 * @export
 * @param {number[]} x
 * @param {number} n
 * @returns {void}
 */
export function addInt_(x: number[], n: number): void {
  var i, k, c, b
  x[0] += n
  k = x.length
  c = 0
  for (i = 0; i < k; i++) {
    c += x[i]
    b = 0
    if (c < 0) {
      b = -(c >> bpe)
      c += b * radix
    }
    x[i] = c & mask
    c = (c >> bpe) - b
    if (!c) return //stop carrying as soon as the carry is zero
  }
}

/**
 * right shift bigInt x by n bits.
 *
 *     0 <= n < bpe.
 *
 * @export
 * @param {number[]} x
 * @param {number} n
 */
export function rightShift_(x: number[], n: number): void {
  var i
  var k = Math.floor(n / bpe)
  if (k) {
    for (
      i = 0;
      i < x.length - k;
      i++ //right shift x by k elements
    )
      x[i] = x[i + k]
    for (; i < x.length; i++) x[i] = 0
    //$off
    n %= bpe
  }
  for (i = 0; i < x.length - 1; i++) {
    x[i] = mask & ((x[i + 1] << (bpe - n)) | (x[i] >> n))
  }
  x[i] >>= n
}

/**
 * do x=floor(|x|/2)*sgn(x) for bigInt x in 2's complement
 *
 * @param {number[]} x
 * @returns {void}
 */
export function halve_(x: number[]): void {
  var i
  for (i = 0; i < x.length - 1; i++) {
    x[i] = mask & ((x[i + 1] << (bpe - 1)) | (x[i] >> 1))
  }
  x[i] = (x[i] >> 1) | (x[i] & (radix >> 1)) //most significant bit stays the same
}

/**
 * left shift bigInt x by n bits
 *
 * @export
 * @param {number[]} x
 * @param {number} n
 * @returns {void}
 */
export function leftShift_(x: number[], n: number): void {
  var i
  var k = Math.floor(n / bpe)
  if (k) {
    for (
      i = x.length;
      i >= k;
      i-- //left shift x by k elements
    )
      x[i] = x[i - k]
    for (; i >= 0; i--) x[i] = 0
    //$off
    n %= bpe
  }
  if (!n) return
  for (i = x.length - 1; i > 0; i--) {
    x[i] = mask & ((x[i] << n) | (x[i - 1] >> (bpe - n)))
  }
  x[i] = mask & (x[i] << n)
}

/**
 * do x=x*n where x is a bigInt and n is an integer.
 *
 * x must be large enough to hold the result.
 *
 * @param {number[]} x
 * @param {number} n
 * @returns {void}
 */
export function multInt_(x: number[], n: number): void {
  var i, k, c, b
  if (!n) return
  k = x.length
  c = 0
  for (i = 0; i < k; i++) {
    c += x[i] * n
    b = 0
    if (c < 0) {
      b = -(c >> bpe)
      c += b * radix
    }
    x[i] = c & mask
    c = (c >> bpe) - b
  }
}

/**
 * do x=floor(x/n) for bigInt x and integer n, and return the remainder
 *
 * @param {number[]} x
 * @param {number} n
 * @returns {number} remainder
 */
export function divInt_(x: number[], n: number): number {
  var i,
      r = 0,
      s
  for (i = x.length - 1; i >= 0; i--) {
    s = r * radix + x[i]
    x[i] = Math.floor(s / n)
    r = s % n
  }
  return r
}

/**
 * do the linear combination x=a*x+b*y for bigInts x and y, and integers a and b.
 *
 * x must be large enough to hold the answer.
 *
 * @param {number[]} x
 * @param {number[]} y
 * @param {number} a
 * @param {number} b
 * @returns {void}
 */
export function linComb_(x: number[], y: number[], a: number, b: number): void {
  var i, c, k, kk
  k = x.length < y.length ? x.length : y.length
  kk = x.length
  for (c = 0, i = 0; i < k; i++) {
    c += a * x[i] + b * y[i]
    x[i] = c & mask
    c >>= bpe
  }
  for (i = k; i < kk; i++) {
    c += a * x[i]
    x[i] = c & mask
    c >>= bpe
  }
}

/**
 * do the linear combination x=a*x+b*(y<<(ys*bpe)) for bigInts x and y, and integers a, b and ys.
 *
 * x must be large enough to hold the answer.
 *
 * @param {number[]} x
 * @param {number[]} y
 * @param {number} b
 * @param {number} ys
 * @returns {void}
 */
export function linCombShift_(
  x: number[],
  y: number[],
  b: number,
  ys: number,
): void {
  var i, c, k, kk
  k = x.length < ys + y.length ? x.length : ys + y.length
  kk = x.length
  for (c = 0, i = ys; i < k; i++) {
    c += x[i] + b * y[i - ys]
    x[i] = c & mask
    c >>= bpe
  }
  for (i = k; c && i < kk; i++) {
    c += x[i]
    x[i] = c & mask
    c >>= bpe
  }
}

/**
 * do x=x+(y<<(ys*bpe)) for bigInts x and y, and integer ys.
 *
 * x must be large enough to hold the answer.
 *
 * @export
 * @param {number[]} x
 * @param {number[]} y
 * @param {number} ys
 * @return {void}
 */
export function addShift_(x: number[], y: number[], ys: number): void {
  var i, c, k, kk
  k = x.length < ys + y.length ? x.length : ys + y.length
  kk = x.length
  for (c = 0, i = ys; i < k; i++) {
    c += x[i] + y[i - ys]
    x[i] = c & mask
    c >>= bpe
  }
  for (i = k; c && i < kk; i++) {
    c += x[i]
    x[i] = c & mask
    c >>= bpe
  }
}

/**
 * do x=x-(y<<(ys*bpe)) for bigInts x and y, and integer ys
 *
 * x must be large enough to hold the answer
 *
 * @param {number[]} x
 * @param {number[]} y
 * @param {number} ys
 * @return {void}
 */
export function subShift_(x: number[], y: number[], ys: number): void {
  var i, c, k, kk
  k = x.length < ys + y.length ? x.length : ys + y.length
  kk = x.length
  for (c = 0, i = ys; i < k; i++) {
    c += x[i] - y[i - ys]
    x[i] = c & mask
    c >>= bpe
  }
  for (i = k; c && i < kk; i++) {
    c += x[i]
    x[i] = c & mask
    c >>= bpe
  }
}

/**
 * do x=x-y for bigInts x and y
 *
 * x must be large enough to hold the answer
 *
 * negative answers will be 2s complement
 *
 * @export
 * @param {number[]} x
 * @param {number[]} y
 * @return {void}
 */
export function sub_(x: number[], y: number[]): void {
  var i, c, k, kk
  k = x.length < y.length ? x.length : y.length
  for (c = 0, i = 0; i < k; i++) {
    c += x[i] - y[i]
    x[i] = c & mask
    c >>= bpe
  }
  for (i = k; c && i < x.length; i++) {
    c += x[i]
    x[i] = c & mask
    c >>= bpe
  }
}

/**
 * do x=x+y for bigInts x and y
 *
 * x must be large enough to hold the answer
 *
 * @export
 * @param {number[]} x
 * @param {number[]} y
 * @return {void}
 */
export function add_(x: number[], y: number[]): void {
  var i, c, k, kk
  k = x.length < y.length ? x.length : y.length
  for (c = 0, i = 0; i < k; i++) {
    c += x[i] + y[i]
    x[i] = c & mask
    c >>= bpe
  }
  for (i = k; c && i < x.length; i++) {
    c += x[i]
    x[i] = c & mask
    c >>= bpe
  }
}

/**
 * do x=x*y for bigInts x and y.
 *
 * This is faster when y<x.
 *
 * @export
 * @param {number[]} x
 * @param {number[]} y
 * @return {void}
 */
export function mult_(x: number[], y: number[]): void {
  var i
  if (ss.length != 2 * x.length) ss = new Array(2 * x.length)
  copyInt_(ss, 0)
  for (i = 0; i < y.length; i++) if (y[i]) linCombShift_(ss, x, y[i], i) //ss=1*ss+y[i]*(x<<(i*bpe))
  copy_(x, ss)
}

/**
 * do x=x mod n for bigInts x and n
 *
 * @export
 * @param {number[]} x
 * @param {number[]} n
 * @return {void}
 */
export function mod_(x: number[], n: number[]): void {
  if (s4.length !== x.length) s4 = dup(x)
  else copy_(s4, x)
  if (s5.length !== x.length) s5 = dup(x)
  divide_(s4, n, s5, x) //x = remainder of s4 / n
}

/**
 * do x=x*y mod n for bigInts x,y,n.
 *
 * for greater speed, let y<x.
 *
 * @param {number[]} x
 * @param {number[]} y
 * @param {number[]} n
 * @return {void}
 */
export function multMod_(x: number[], y: number[], n: number[]): void {
  var i
  if (s0.length != 2 * x.length) s0 = new Array(2 * x.length)
  copyInt_(s0, 0)
  for (i = 0; i < y.length; i++) if (y[i]) linCombShift_(s0, x, y[i], i) //s0=1*s0+y[i]*(x<<(i*bpe))
  mod_(s0, n)
  copy_(x, s0)
}

/**
 * do x=x*x mod n for bigInts x,n.
 *
 * @export
 * @param {number[]} x
 * @param {number[]} n
 * @return {void}
 */
export function squareMod_(x: number[], n: number[]): void {
  var i, j, d, c, kx, kn, k
  for (kx = x.length; kx > 0 && !x[kx - 1]; kx--); //ignore leading zeros in x
  k = kx > n.length ? 2 * kx : 2 * n.length //k=# elements in the product, which is twice the elements in the larger of x and n
  if (s0.length != k) s0 = new Array(k)
  copyInt_(s0, 0)
  for (i = 0; i < kx; i++) {
    c = s0[2 * i] + x[i] * x[i]
    s0[2 * i] = c & mask
    c >>= bpe
    for (j = i + 1; j < kx; j++) {
      c = s0[i + j] + 2 * x[i] * x[j] + c
      s0[i + j] = c & mask
      c >>= bpe
    }
    s0[i + kx] = c
  }
  mod_(s0, n)
  copy_(x, s0)
}

/**
 * return x with exactly k leading zero elements
 *
 * @export
 * @param {number[]} x
 * @param {number} k
 * @returns {number[]}
 */
export function trim(x: number[], k: number): number[] {
  var i, y
  for (i = x.length; i > 0 && !x[i - 1]; i--);
  y = new Array(i + k)
  copy_(y, x)
  return y
}

/**
 * do `x=x**y mod n`, where x,y,n are bigInts and `**` is exponentiation.  `0**0=1`.
 *
 * this is faster when n is odd.
 *
 * x usually needs to have as many elements as n.
 *
 * @param {number[]} x
 * @param {number[]} y
 * @param {number[]} n
 * @return {void}
 */
export function powMod_(x: number[], y: number[], n: number[]): void {
  var k1, k2, kn, np
  if (s7.length != n.length) s7 = dup(n)

  //for even modulus, use a simple square-and-multiply algorithm,
  //rather than using the more complex Montgomery algorithm.
  if ((n[0] & 1) == 0) {
    copy_(s7, x)
    copyInt_(x, 1)
    while (!equalsInt(y, 0)) {
      if (y[0] & 1) multMod_(x, s7, n)
      divInt_(y, 2)
      squareMod_(s7, n)
    }
    return
  }

  //calculate np from n for the Montgomery multiplications
  copyInt_(s7, 0)
  for (kn = n.length; kn > 0 && !n[kn - 1]; kn--);
  np = radix - inverseModInt(modInt(n, radix), radix)
  s7[kn] = 1
  multMod_(x, s7, n) // x = x * 2**(kn*bp) mod n

  if (s3.length != x.length) s3 = dup(x)
  else copy_(s3, x)
  //$off
  for (k1 = y.length - 1; (k1 > 0) & !y[k1]; k1--); //k1=first nonzero element of y
  if (y[k1] == 0) {
    //anything to the 0th power is 1
    copyInt_(x, 1)
    return
  }
  for (k2 = 1 << (bpe - 1); k2 && !(y[k1] & k2); k2 >>= 1); //k2=position of first 1 bit in y[k1]
  for (;;) {
    if (!(k2 >>= 1)) {
      //look at next bit of y
      k1--
      if (k1 < 0) {
        mont_(x, one, n, np)
        return
      }
      k2 = 1 << (bpe - 1)
    }
    mont_(x, x, n, np)

    if (k2 & y[k1])
      //if next bit is a 1
      mont_(x, s3, n, np)
  }
}

/**
 * do x=x*y*Ri mod n for bigInts x,y,n,
 * where Ri = 2**(-kn*bpe) mod n, and kn is the
 * number of elements in the n array, not
 * counting leading zeros.
 *
 * x array must have at least as many elemnts as the n array
 * It's OK if x and y are the same variable.
 *
 * must have:
 *  * x,y < n
 *  * n is odd
 *  * np = -(n^(-1)) mod radix
 *
 * @export
 * @param {number[]} x
 * @param {number[]} y
 * @param {number[]} n
 * @param {number} np
 * @return {void}
 */
export function mont_(x: number[], y: number[], n: number[], np: number): void {
  var i, j, c, ui, t, ks
  var kn = n.length
  var ky = y.length

  if (sa.length != kn) sa = new Array(kn)

  copyInt_(sa, 0)

  for (; kn > 0 && n[kn - 1] == 0; kn--); //ignore leading zeros of n
  for (; ky > 0 && y[ky - 1] == 0; ky--); //ignore leading zeros of y
  ks = sa.length - 1 //sa will never have more than this many nonzero elements.

  //the following loop consumes 95% of the runtime for randTruePrime_() and powMod_() for large numbers
  for (i = 0; i < kn; i++) {
    t = sa[0] + x[i] * y[0]
    ui = ((t & mask) * np) & mask //the inner "& mask" was needed on Safari (but not MSIE) at one time
    c = (t + ui * n[0]) >> bpe
    t = x[i]

    //do sa=(sa+x[i]*y+ui*n)/b   where b=2**bpe.  Loop is unrolled 5-fold for speed
    j = 1
    for (; j < ky - 4; ) {
      c += sa[j] + ui * n[j] + t * y[j]
      sa[j - 1] = c & mask
      c >>= bpe
      j++
      c += sa[j] + ui * n[j] + t * y[j]
      sa[j - 1] = c & mask
      c >>= bpe
      j++
      c += sa[j] + ui * n[j] + t * y[j]
      sa[j - 1] = c & mask
      c >>= bpe
      j++
      c += sa[j] + ui * n[j] + t * y[j]
      sa[j - 1] = c & mask
      c >>= bpe
      j++
      c += sa[j] + ui * n[j] + t * y[j]
      sa[j - 1] = c & mask
      c >>= bpe
      j++
    }
    for (; j < ky; ) {
      c += sa[j] + ui * n[j] + t * y[j]
      sa[j - 1] = c & mask
      c >>= bpe
      j++
    }
    for (; j < kn - 4; ) {
      c += sa[j] + ui * n[j]
      sa[j - 1] = c & mask
      c >>= bpe
      j++
      c += sa[j] + ui * n[j]
      sa[j - 1] = c & mask
      c >>= bpe
      j++
      c += sa[j] + ui * n[j]
      sa[j - 1] = c & mask
      c >>= bpe
      j++
      c += sa[j] + ui * n[j]
      sa[j - 1] = c & mask
      c >>= bpe
      j++
      c += sa[j] + ui * n[j]
      sa[j - 1] = c & mask
      c >>= bpe
      j++
    }
    for (; j < kn; ) {
      c += sa[j] + ui * n[j]
      sa[j - 1] = c & mask
      c >>= bpe
      j++
    }
    for (; j < ks; ) {
      c += sa[j]
      sa[j - 1] = c & mask
      c >>= bpe
      j++
    }
    sa[j - 1] = c & mask
  }

  if (!greater(n, sa)) sub_(sa, n)
  copy_(x, sa)
}
//@flow

import {
  str2bigInt,
  bigInt2str,
} from '..'

describe('str2bigInt', () => {
  test('should process uppercase hexes with numeral base', () => {
    expect(str2bigInt('C', 16)).toEqual([12, 0])
    expect(str2bigInt('C', 16, 5)).toEqual([12, 0, 0, 0, 0])
  })
  test('should process lowercase hexes with numeral base', () => {
    expect(str2bigInt('c', 16)).toEqual([12, 0])
    expect(str2bigInt('c', 16, 5)).toEqual([12, 0, 0, 0, 0])
  })
  test('test data', () => {
    expect(
      str2bigInt('313aada96ad', 16, 6)
    ).toEqual([5805, 21941, 3150, 0, 0, 0])
  })
})

test('bigInt2str', () => {
  expect(bigInt2str([5805, 21941, 3150, 0, 0, 0], 10)).toBe('3383005714093')
  expect(bigInt2str([4949, 9, 0, 0, 0, 0], 10)).toBe('299861')
  expect(bigInt2str([9721, 344, 0, 0, 0, 0], 10)).toBe('11281913')
  expect(bigInt2str([4949, 9, 0, 0, 0, 0], 16)).toBe('49355')
  expect(bigInt2str([9721, 344, 0, 0, 0, 0], 16)).toBe('AC25F9')
})
